<script setup lang="ts">
import { computed, onMounted, ref, defineAsyncComponent } from 'vue';
import { MapPin, Clock3, Users, Building2, ExternalLink, CheckCircle2, TriangleAlert } from '@lucide/vue';
import { api } from '../services/api'; import { type Hazard, type User, type Department, type Status, labels, transitions, relativeTime, active } from '../types';
import HazardIcon from './HazardIcon.vue';
import ConfirmDialog from './ConfirmDialog.vue';
import EvidencePhotos from './EvidencePhotos.vue';
import { compressPhoto } from '../services/mediaService';
const HazardMap = defineAsyncComponent(() => import('./HazardMap.vue'));
const props = defineProps<{ initial: Hazard; user: User | null; departments: Department[]; demo: boolean }>(); const emit = defineEmits<{ updated: []; deleted: [] }>();
const pendingAction = ref<'update' | 'delete' | 'confirm' | null>(null); const report = ref(props.initial); const error = ref(''); const message = ref(''); const busy = ref(false); const status = ref<Status>(props.initial.status); const severity = ref(props.initial.severity); const department = ref(props.initial.department.id); const responder = ref(''); const note = ref('');
const point = ref({ latitude: props.initial.verified_latitude ?? props.initial.selected_latitude, longitude: props.initial.verified_longitude ?? props.initial.selected_longitude });
const admin = computed(() => props.user?.role === 'admin');
const loading = ref(!!props.user && !props.demo); const privateLoaded = ref(false);
const publicTitle = ref(''); const publicSummary = ref(''); const publish = ref(false);
const publicStatuses = ['verified', 'assigned', 'responding', 'resolved', 'closed'];
const resolutionFiles = ref<File[]>([]); const processing = ref(false); const uploadInput = ref<HTMLInputElement>();
const resolutionCount = computed(() => report.value.photos.filter(photo => photo.photo_type === 'resolution').length);
const dateTime = (value: string) => new Date(value).toLocaleString('en-PH', { timeZone: 'Asia/Manila' }) + ' PHT';
const gps = computed(() => report.value.gps_latitude != null && report.value.gps_longitude != null ? { latitude: report.value.gps_latitude, longitude: report.value.gps_longitude, accuracy: report.value.gps_accuracy || 0 } : undefined);
onMounted(async () => {
  if (props.user && !props.demo) {
    try {
      const result = await api<{ data: Hazard }>(`/api/reports/${report.value.id}`);
      report.value = result.data; privateLoaded.value = true;
      responder.value = report.value.assigned_responder || '';
      publicTitle.value = report.value.public_title || ''; publicSummary.value = report.value.public_summary || ''; publish.value = !!report.value.public_summary;
      point.value = { latitude: report.value.verified_latitude ?? report.value.selected_latitude, longitude: report.value.verified_longitude ?? report.value.selected_longitude };
    } catch (e) { if (admin.value || props.initial.user_id === props.user.id) error.value = (e as Error).message; }
    finally { loading.value = false; }
  }
});
async function chooseResolution(event: Event) {
  processing.value = true; error.value = '';
  try {
    const selected = Array.from((event.target as HTMLInputElement).files || []);
    if (selected.length > 3 - resolutionCount.value) throw new Error('A report may have up to three resolution photos.');
    const compressed = []; for (const file of selected) compressed.push(await compressPhoto(file)); resolutionFiles.value = compressed;
  } catch (e) { resolutionFiles.value = []; error.value = (e as Error).message; }
  finally { processing.value = false; }
}
async function uploadResolution() {
  if (!resolutionFiles.value.length || busy.value) return;
  busy.value = true; error.value = ''; message.value = '';
  try {
    const data = new FormData(); resolutionFiles.value.forEach(file => data.append('photos[]', file));
    await api(`/api/reports/${report.value.id}/resolution-photos`, { method: 'POST', body: data });
    report.value = (await api<{ data: Hazard }>(`/api/reports/${report.value.id}`)).data;
    resolutionFiles.value = []; if (uploadInput.value) uploadInput.value.value = '';
    message.value = 'Resolution photos saved privately.'; emit('updated');
  } catch (e) { error.value = (e as Error).message; }
  finally { busy.value = false; }
}
async function update() { busy.value = true; error.value = ''; message.value = ''; try { report.value = (await api<{ data: Hazard }>(`/api/reports/${report.value.id}`, { method: 'PATCH', body: JSON.stringify({ status: status.value, severity: severity.value, department_id: department.value, assigned_responder: responder.value || null, note: note.value, verified_latitude: point.value.latitude, verified_longitude: point.value.longitude, public_title: publish.value && publicStatuses.includes(status.value) ? publicTitle.value : null, public_summary: publish.value && publicStatuses.includes(status.value) ? publicSummary.value : null }) })).data; status.value = report.value.status; note.value = ''; message.value = 'Response updated. A notification is available to the reporter.'; pendingAction.value = null; emit('updated'); } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } }
async function confirm() { busy.value = true; error.value = ''; try { await api(`/api/reports/${report.value.id}/confirm`, { method: 'POST' }); message.value = 'Thank you. Your confirmation has been recorded.'; pendingAction.value = null; emit('updated'); } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } }
async function remove() { busy.value = true; error.value = ''; try { await api(`/api/reports/${report.value.id}`, { method: 'DELETE' }); pendingAction.value = null; emit('deleted'); } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } }
</script>
<template><div v-if="loading" class="private-detail-loading" role="status">Loading report details?</div><div v-else class="form-body"><div class="detail-title"><div class="category-icon" :class="report.category.id"><HazardIcon :category="report.category.id" :size="25" /></div><div><span class="eyebrow">{{ report.reference_number }}</span><h3>{{ report.title }}</h3></div></div><div class="detail-badges"><span class="status" :class="report.status">{{ labels[report.status] }}</span><span class="severity" :class="report.severity">{{ report.severity }} priority</span></div><p class="description">{{ report.description }}</p><div v-if="privateLoaded" class="notice neutral">Private report ? Evidence, exact location and response notes are shared only with the reporter and authorized municipal administrators.</div><dl v-if="privateLoaded" class="incident-facts"><div><dt>Incident time</dt><dd>{{ report.occurred_at ? dateTime(report.occurred_at) : 'Not supplied; submission time is recorded separately' }}</dd></div><div><dt>Injuries observed</dt><dd>{{ report.injuries === 'yes' ? 'Injuries reported ? contact emergency services' : report.injuries === 'no' ? 'None observed by reporter' : 'Not sure' }}</dd></div><div><dt>People affected</dt><dd>{{ report.people_affected != null ? `${report.people_affected.toLocaleString()} (reporter estimate)` : 'Unknown' }}</dd></div></dl><EvidencePhotos v-if="privateLoaded" :photos="report.photos" kind="incident" /><EvidencePhotos v-if="privateLoaded" :photos="report.photos" kind="resolution" /><div class="detail-facts"><p><MapPin :size="17" /><span>{{ report.address }}<small>Barangay {{ report.barangay }}</small></span></p><p><Clock3 :size="17" /><span>{{ relativeTime(report.created_at) }}<small>{{ dateTime(report.created_at) }}</small></span></p><p><Building2 :size="17" /><span>{{ report.department.name }}</span></p><p><Users :size="17" /><span>{{ report.confirmations_count }} community confirmations</span></p></div><p v-if="report.approximate_location" class="notice neutral">The public map shows an approximate area. Exact incident coordinates and evidence are private. Use emergency services for immediate help.</p><a v-else class="text-button inline-link" target="_blank" rel="noreferrer" :href="`https://www.google.com/maps/dir/?api=1&destination=${point.latitude},${point.longitude}`"><ExternalLink :size="15" />Get directions to the reported location</a>
  <section v-if="report.location_source" class="location-evidence"><h3>Location evidence</h3><div v-if="report.location_review_required" class="notice emergency"><TriangleAlert :size="20" /><p><strong>Location needs review</strong>A large GPS difference or low accuracy needs verification. It does not mean the report is invalid.</p></div><dl><div><dt>Selected hazard location</dt><dd>{{ report.selected_latitude.toFixed(6) }}, {{ report.selected_longitude.toFixed(6) }}</dd></div><div><dt>Phone GPS</dt><dd>{{ gps ? `${gps.latitude.toFixed(6)}, ${gps.longitude.toFixed(6)}` : 'Not provided — manually pinned' }}</dd></div><div><dt>Difference</dt><dd>{{ report.location_difference_meters != null ? `${report.location_difference_meters.toLocaleString()} meters` : 'Not available' }}</dd></div><div><dt>GPS accuracy / source</dt><dd>{{ gps ? `±${Math.round(gps.accuracy)} m · ` : '' }}{{ report.location_source.replace('_', ' ') }}</dd></div><div><dt>Verified location</dt><dd>{{ report.verified_latitude != null ? `${report.verified_latitude.toFixed(6)}, ${report.verified_longitude?.toFixed(6)}` : 'Awaiting municipal verification' }}</dd></div></dl></section>
  <section v-if="report.history" class="timeline"><h3>Report timeline</h3><div v-for="item in report.history" :key="item.id" class="timeline-item"><CheckCircle2 :size="17" /><div><strong>{{ labels[item.status] }}</strong><p>{{ item.note }}</p><small>{{ dateTime(item.created_at) }}</small></div></div></section>
  <p v-if="!user" class="notice neutral">Sign in to confirm a hazard. Reporters can also view their report history.</p><button v-if="user && !admin && active(report.status) && report.user_id !== user.id && !demo" class="button secondary" :disabled="busy || !!message" @click="pendingAction = 'confirm'"><CheckCircle2 :size="17" />I can confirm this hazard</button>
  <section v-if="admin && privateLoaded && !demo && ['assigned', 'responding', 'resolved'].includes(report.status) && resolutionCount < 3" class="resolution-upload"><h3>Add resolution photos</h3><p class="field-help">Up to 3 resolution photos, separate from incident evidence. Avoid faces and personal details. Photos remain private.</p><label>Resolution evidence<input ref="uploadInput" type="file" accept="image/jpeg,image/png,image/webp" multiple :disabled="processing || busy" @change="chooseResolution"></label><p v-if="processing" role="status">Preparing photos?</p><button type="button" class="button secondary" :disabled="!resolutionFiles.length || busy || processing" @click="uploadResolution">{{ busy ? 'Uploading?' : 'Upload resolution photos' }}</button></section>
  <form v-if="admin && privateLoaded && !demo && !['closed', 'rejected'].includes(report.status)" class="admin-form" @submit.prevent="pendingAction = 'update'"><h3>Municipal response</h3><p v-if="report.reporter" class="field-help">Reported by {{ report.reporter.name }} · {{ report.reporter.email }}</p><label>Verify the hazard location<span class="field-help">Tap the map or drag the green pin. The blue dot shows the original GPS.</span><div class="picker-map"><HazardMap style-selector :pin="point" :gps="gps" editable @pick="point = $event" /></div></label><div class="form-grid"><label>Verified latitude<input v-model.number="point.latitude" type="number" step="any" min="-90" max="90" required></label><label>Verified longitude<input v-model.number="point.longitude" type="number" step="any" min="-180" max="180" required></label></div><div class="form-grid"><label>Status<select v-model="status"><option v-for="item in [report.status, ...transitions[report.status]]" :key="item" :value="item">{{ labels[item] }}</option></select></label><label>Priority<select v-model="severity"><option v-for="item in ['low', 'moderate', 'high', 'critical']" :key="item">{{ item }}</option></select></label></div><label>Department<select v-model="department" required><option v-for="item in departments" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>Assigned responder or team<input v-model="responder" :required="status === 'assigned'" minlength="2" maxlength="100" placeholder="e.g. Engineering response team 1"></label><label>Response update<textarea v-model="note" rows="3" required minlength="5" maxlength="1000" placeholder="This update will be visible to the reporter."></textarea></label><section v-if="publicStatuses.includes(status)" class="public-summary-fields"><label class="checkbox-label"><input v-model="publish" type="checkbox">Publish a separate community summary</label><p class="field-help">Review this text for privacy. Leave out names, injury details, exact addresses and other identifying information. Original photos and descriptions remain private.</p><template v-if="publish"><label>Public title<input v-model="publicTitle" minlength="5" maxlength="120" :required="publish"></label><label>Public summary<textarea v-model="publicSummary" rows="3" minlength="15" maxlength="1000" :required="publish"></textarea></label></template></section><button class="button primary full" :disabled="busy || processing">{{ busy ? 'Saving…' : 'Save response update' }}</button></form>
  <button v-if="user && user.id === report.user_id && ['submitted', 'under_verification'].includes(report.status) && !demo" class="button danger" :disabled="busy" @click="pendingAction = 'delete'">Delete unverified report</button>
  <p v-if="error" class="form-error" role="alert">{{ error }}</p><p v-if="message" class="notice success" role="status">{{ message }}</p>
</div><ConfirmDialog v-if="pendingAction" :title="pendingAction === 'delete' ? 'Delete this report?' : pendingAction === 'update' ? 'Save municipal response?' : 'Confirm this hazard?'" :message="pendingAction === 'delete' ? 'The report will be removed from public listings. This action cannot be undone by you.' : pendingAction === 'update' ? 'The new status and note will be visible to the reporter.' : 'Your confirmation will be recorded for municipal review.'" :danger="pendingAction === 'delete'" :busy="busy" :error="error" :confirm-label="pendingAction === 'delete' ? 'Delete report' : pendingAction === 'update' ? 'Save response' : 'Confirm hazard'" @close="pendingAction = null" @confirm="pendingAction === 'delete' ? remove() : pendingAction === 'update' ? update() : confirm()" /></template>
